import os
import re
import shutil

from functools import partial
from zipfile import ZipFile

from ute_common_util.context import NewSession
from ute_fsmaccess import ute_fsmaccess


class AdaptationVersions(object):
    def get_from_enb(self, enb_ip='192.168.255.1', partition='active', output_dir='.', remote_host=None):
        """Downloads the AdaptationVersions file from given partition of eNB to
           output_dir and returns its path, or None if it is unavailable."""
        partition_path = '/ffs/run/' if partition == 'active' else '/ffs/stb/'
        enb_session = ute_fsmaccess()
        setup_method = partial(enb_session.setup_enb_fsm_access, host=enb_ip, remote_host=remote_host)
        with NewSession(
            enb_session, setup=setup_method, teardown=enb_session.teardown_enb_fsm_access
        ) as new_enb_session:
            find_command = 'cd {}; ls AdaptationVersions*.xml'.format(partition_path)
            output, rc = new_enb_session.execute_command_on_enb(find_command, return_rc=True)
            if rc != 0:
                return None
            file_name = output.splitlines()[0]
            source = os.path.join(partition_path, file_name)
            destination = os.path.join(output_dir, file_name)
            new_enb_session.get_enb_file(source, destination)
        return destination

    def get_from_enb_sw_zip(self, sw_zip_path, output_dir='.'):
        """Extracts the AdaptationVersions file from given eNB SW package to output_dir.
           Both puttibatti- and BTSSM-based packages are supported.
           Returns the path where the file was extracted or None if it is unavailable."""
        sw_zip = ZipFile(sw_zip_path)
        matching_files = [path for path in sw_zip.namelist() if re.match('.*AdaptationVersions.*.xml$', path)]
        if matching_files:
            return self._extract_to_dir(sw_zip, matching_files[0], output_dir)
        else:
            return None

    def _extract_to_dir(self, zip, path_in_zip, output_dir):
        dest_file_name = os.path.join(output_dir, os.path.basename(path_in_zip))
        with zip.open(path_in_zip) as source_file, open(dest_file_name, 'w') as dest_file:
            shutil.copyfileobj(source_file, dest_file)
        return dest_file_name

    def find_in_directory(self, directory):
        """Returns the path to the AdaptationVersions file in given directory, or None if it could not be found."""
        matching_files = [
            file_name for file_name in os.listdir(directory) if re.match('AdaptationVersions.*xml', file_name)
        ]
        return os.path.join(directory, matching_files[0]) if matching_files else None
